UNITS = {'s': 1, 'm': 60, 'h': 3600}

def parse_duration(text):
    if not text or text[-1] not in UNITS:
        raise ValueError('unknown duration unit: ' + repr(text))
    return int(text[:-1]) * UNITS[text[-1]]

