UNITS = ('B', 'KiB', 'MiB', 'GiB')

def human_bytes(n):
    value = float(n)
    index = 0
    while value >= 1024 and index < len(UNITS) - 1:
        value /= 1024
        index += 1
    if index == 0:
        return '%d %s' % (int(value), UNITS[index])
    return '%.1f %s' % (value, UNITS[index])

